@startuml

class Customer {
  + Name : string
  + AccountNumber : string
}

class Broker {
  + Name : string
}

class Policy {
  + Price : float
}

class Contract {
  + OfferDate : date
  + SigningDate : date
  + BillingCycle : string
}

class ClaimCase {
  + CaseNumber : string
  + Status : string
}

class Estimator {
  + Name : string
  + Expertise : string
}

class EstimatorReport {
  + ReportContent : string
  + DateIssued : date
}

class Compensation {
  + Amount : float
  + DatePaid : date
}

class AlphaInsurance {}

Broker "1" -- "*" Customer : manages
Customer "1" -- "*" Contract : signs
Contract "1" -- "1" Policy : is based on
Customer "1" -- "*" ClaimCase : files
ClaimCase "1" *-- "1..*" EstimatorReport : contains
Estimator "1" -- "*" EstimatorReport : issues
ClaimCase "1" -- "0..1" Compensation : results in
AlphaInsurance -- Broker
AlphaInsurance -- Customer
AlphaInsurance -- ClaimCase

@enduml

